func SetIdNEQ(v uuid.UUID) predicate.Source {
	return predicate.Source(sql.FieldNEQ(FieldSetId, v))
}

// SetIdIn applies the In predicate on the "set_id" field.
func SetIdIn(vs ...uuid.UUID) predicate.Source {
	return predicate.Source(sql.FieldIn(FieldSetId, vs...))
}

// SetIdNotIn applies the NotIn predicate on the "set_id" field.
func SetIdNotIn(vs ...uuid.UUID) predicate.Source {
	return predicate.Source(sql.FieldNotIn(FieldSetId, vs...))
}

// HasTenant applies the HasEdge predicate on the "tenant" edge.
func HasTenant() predicate.Source {
	return predicate.Source(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldId),
			sqlgraph.Edge(sqlgraph.M2O, false, TenantTable, TenantColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTenantWith applies the HasEdge predicate on the "tenant" edge with a given conditions (other predicates).
func HasTenantWith(preds ...predicate.Tenant) predicate.Source {
	return predicate.Source(func(s *sql.Selector) {
		step := newTenantStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

